previewCss:
.darma-loader-darma-b8-solar-system { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 96px); height: var(--loader-size, 96px); position: relative; }
.darma-loader-darma-b8-solar-system::before { content: ''; position: absolute; inset: 0; margin: auto; width: 22%; height: 22%; border-radius: 50%; background: radial-gradient(circle at 40% 35%, #fff, var(--accent) 60%); box-shadow: 0 0 calc(var(--loader-size, 96px) * .18) var(--accent); }
.darma-loader-darma-b8-solar-system span { position: absolute; inset: 0; margin: auto; border: 1px solid color-mix(in srgb, var(--accent-2) 30%, transparent); border-radius: 50%; }
.darma-loader-darma-b8-solar-system span::after { content: ''; position: absolute; top: calc(var(--loader-size, 96px) * -.045); left: 50%; width: calc(var(--loader-size, 96px) * .09); height: calc(var(--loader-size, 96px) * .09); margin-left: calc(var(--loader-size, 96px) * -.045); border-radius: 50%; background: var(--accent-2); box-shadow: 0 0 calc(var(--loader-size, 96px) * .08) var(--accent-2); }
.darma-loader-darma-b8-solar-system span:nth-child(1) { width: 46%; height: 46%; animation: darma-loader-darma-b8-solar-system-orbit calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b8-solar-system span:nth-child(2) { width: 72%; height: 72%; animation: darma-loader-darma-b8-solar-system-orbit calc(var(--loader-speed, 1s) * 2.7) linear infinite; }
.darma-loader-darma-b8-solar-system span:nth-child(3) { width: 98%; height: 98%; animation: darma-loader-darma-b8-solar-system-orbit calc(var(--loader-speed, 1s) * 4) linear infinite; }
@keyframes darma-loader-darma-b8-solar-system-orbit { to { rotate: 360deg; } }

